CREATE OR REPLACE FUNCTION public.app_admin_list_opportunity_applications(p_opportunity_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_role TEXT;
    v_result JSONB;
BEGIN
    IF v_user_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_authenticated');
    END IF;

    SELECT raw_user_meta_data->>'role'
    INTO v_role
    FROM auth.users
    WHERE id = v_user_id;

    IF v_role <> 'admin' THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_admin');
    END IF;

    SELECT COALESCE(
        JSONB_AGG(
            JSONB_BUILD_OBJECT(
                'application_id', a.id,
                'opportunity_id', a.opportunity_id,
                'student_id', a.student_id,
                'status', a.status,
                'message', a.message,
                'cv_url', a.cv_url,
                'extra_data', a.extra_data,
                'created_at', a.created_at,
                'updated_at', a.updated_at
            )
            ORDER BY a.created_at DESC
        ),
        '[]'::JSONB
    ) INTO v_result
    FROM app.opportunity_applications a
    WHERE a.opportunity_id = p_opportunity_id;

    RETURN JSONB_BUILD_OBJECT('success', TRUE, 'applications', v_result);
END;
$function$

CREATE OR REPLACE FUNCTION public.app_admin_list_opportunity_types()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_role TEXT;
    v_result JSONB;
BEGIN
    IF v_user_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_authenticated');
    END IF;

    SELECT raw_user_meta_data->>'role'
    INTO v_role
    FROM auth.users
    WHERE id = v_user_id;

    IF v_role <> 'admin' THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_admin');
    END IF;

    SELECT COALESCE(
        JSONB_AGG(
            JSONB_BUILD_OBJECT(
                'id', t.id,
                'code', t.code,
                'label', t.label,
                'sort_order', t.sort_order,
                'is_active', t.is_active,
                'created_at', t.created_at,
                'updated_at', t.updated_at
            )
            ORDER BY t.sort_order, t.label ASC
